module TopModule (
    input  logic clk,
    input  logic aresetn,
    input  logic x,
    output logic z
);

    typedef enum logic [1:0] {
        S0  = 2'b00,
        S1  = 2'b01,
        S10 = 2'b10
    } state_t;

    state_t state, next_state;

    // Sequential logic with asynchronous negative-edge reset
    always_ff @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end

    // Combinational next-state and Mealy output logic
    always_comb begin
        next_state = state;
        z = 1'b0;

        case (state)
            S0: begin
                if (x) begin
                    next_state = S1;
                end else begin
                    next_state = S0;
                end
            end

            S1: begin
                if (x) begin
                    next_state = S1;
                end else begin
                    next_state = S10;
                end
            end

            S10: begin
                if (x) begin
                    z = 1'b1;
                    next_state = S1;
                end else begin
                    next_state = S0;
                end
            end

            default: begin
                next_state = S0;
            end
        endcase
    end

endmodule

